CREATE TABLE IF NOT EXISTS public.program_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), program_id uuid NOT NULL REFERENCES public.programs(id) ON DELETE CASCADE, revision_no int NOT NULL, snapshot jsonb NOT NULL, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (program_id, revision_no)); CREATE INDEX IF NOT EXISTS program_revisions_program_idx ON public.program_revisions (program_id, revision_no DESC); ALTER TABLE public.program_revisions ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Owners read program revisions" ON public.program_revisions; CREATE POLICY "Owners read program revisions" ON public.program_revisions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.programs p WHERE p.id = program_id AND p.owner_id = (select auth.uid()))); DROP POLICY IF EXISTS "Assigned clients read program revisions" ON public.program_revisions; CREATE POLICY "Assigned clients read program revisions" ON public.program_revisions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.program_assignments pa WHERE pa.program_id = program_revisions.program_id AND pa.client_id = (select auth.uid()) AND pa.status IN ('active', 'paused'))); DROP POLICY IF EXISTS "Coaches read client program revisions" ON public.program_revisions; CREATE POLICY "Coaches read client program revisions" ON public.program_revisions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.program_assignments pa WHERE pa.program_id = program_revisions.program_id AND public.is_coach_of(pa.client_id))); GRANT SELECT ON TABLE public.program_revisions TO authenticated;
